#!/usr/bin/env bash
# 노트북용: thirdimpact 작업공간의 pitwall에 MPC monitor 패널(JSND_INT 8c35270, 2파일)만 반영하고 pitwall만 빌드.
# 실행(노트북): ssh jsnd@172.20.10.4 'cat JSND_INT/laptop_pitwall_mpc/install_pitwall_mpc_panel.sh' | bash
# 재실행 안전. 원본이 아닌 로컬 수정이 있으면 덮어쓰지 않고 중단.
set -eo pipefail
H=race_utils/pitwall/include/pitwall/pitwall_panel.hpp
C=race_utils/pitwall/src/pitwall_panel.cpp
H_OLD=9aa483644e26fc3e3117142d51b0fdeed7f8eb1b34c8e51bd6318c22ecf0ed97; H_NEW=ccae99217f70d495aabc37fabc8384c01e935c1f7c398d7fd2a0a7e0439b1103
C_OLD=8e6aa8b2af4ab79f40ea65f7e82e63c9b386cb5ea55a7a542e775ca70eb15473; C_NEW=8fa41fc1a6366888caeb7adaa83fb719cf5a453513860f0900767b7ab9ef4f24
H_B64=''
C_B64=''
die(){ echo "[pitwall-mpc] 중단: $*" >&2; exit 1; }
# 1) thirdimpact alias -> 실제 저장소/작업공간
TI=$(grep -hoE "alias thirdimpact=['\"]?source [^'\"]+" ~/.bashrc ~/.zshrc 2>/dev/null | head -1 | sed -E 's/.*source[[:space:]]+//' || true)
TI=${TI//\$HOME/$HOME}; TI=${TI/#\~/$HOME}
[ -n "$TI" ] && [ -f "$TI" ] || die "~/.bashrc/~/.zshrc 에서 alias thirdimpact 를 못 찾음 (TI='$TI')"
REPO=$(cd "$(dirname "$TI")" && pwd); WS=$(cd "$REPO/../.." && pwd)
echo "[pitwall-mpc] thirdimpact=$TI"; echo "[pitwall-mpc] repo=$REPO"; echo "[pitwall-mpc] ws=$WS"
[ -d "$REPO/race_utils/pitwall" ] || die "$REPO/race_utils/pitwall 없음"
# 2) 2파일 반영
put(){ local rel=$1 old=$2 new=$3 b64=$4 dst="$REPO/$1" cur
  cur=$(sha256sum < "$dst" | cut -d' ' -f1)
  if [ "$cur" = "$new" ]; then echo "[pitwall-mpc] 이미 반영: $rel"; return; fi
  [ "$cur" = "$old" ] || die "$rel 가 원본/새 버전과 다름(로컬 수정?). 덮어쓰지 않음"
  cp -p "$dst" "$dst.bak_$(date +%Y%m%d_%H%M%S)"
  printf '%s' "$b64" | base64 -d > "$dst.new"
  [ "$(sha256sum < "$dst.new" | cut -d' ' -f1)" = "$new" ] || die "$rel 해시 불일치"
  mv "$dst.new" "$dst"; echo "[pitwall-mpc] 반영: $rel (백업 .bak_*)"; }
put "$H" "$H_OLD" "$H_NEW" "$H_B64"
put "$C" "$C_OLD" "$C_NEW" "$C_B64"
# 3) pitwall만 빌드 (thirdimpact 환경)
set +e; source "$TI" >/dev/null 2>&1; set -e
[ -n "$ROS_DISTRO" ] || die "thirdimpact 환경 로드 실패"
cd "$WS"
colcon build --base-paths "$REPO/race_utils/pitwall" --packages-select pitwall --symlink-install \
  --cmake-args -DCMAKE_BUILD_TYPE=Release -DCMAKE_POLICY_VERSION_MINIMUM=3.5
SO=$(ls "$WS"/install/pitwall/lib/libpitwall_panel.* 2>/dev/null | head -1)
[ -n "$SO" ] && grep -aq "pitwall/mpc_monitor" "$SO" || die "빌드 결과에 MPC monitor 없음 ($SO)"
echo "[pitwall-mpc] 완료: $SO 에 MPC monitor 포함. 새 터미널에서  thirdimpact  →  pitwall"
